title:
try {
    System.out.println("1. try");
    int n = 10 / 0; // 예외 발생
    System.out.println("2. try - 실행 안 됨");
} catch (ArithmeticException e) {
    System.out.println("3. catch");
} finally {
    System.out.println("4. finally - 항상 실행");
}
// 출력: 1 → 3 → 4

